create function public.workspace_prepare_worker(p_email text,p_worker text,p_name text,p_company text) returns void language sql security definer set search_path='' as $$ insert into private.directory(email,worker_id,name,company,role) values(lower(p_email),p_worker,p_name,p_company,'worker') $$;
create function public.workspace_cancel_worker(p_email text) returns void language sql security definer set search_path='' as $$ delete from private.directory where email=p_email and role='worker' and not exists(select 1 from auth.users where lower(email)=p_email) $$;
create function public.workspace_change_worker_id(p_id uuid,p_worker text) returns void language plpgsql security definer set search_path='' as $$ begin update private.directory set worker_id=p_worker where email=(select lower(email) from auth.users where id=p_id);update public.members set worker_id=p_worker where id=p_id;end $$;
revoke all on function public.workspace_prepare_worker(text,text,text,text),public.workspace_cancel_worker(text),public.workspace_change_worker_id(uuid,text) from public,anon,authenticated;
grant execute on function public.workspace_prepare_worker(text,text,text,text),public.workspace_cancel_worker(text),public.workspace_change_worker_id(uuid,text) to service_role;
